(() => {
  'use strict';

  // ---------- 定数 ----------
  // ジッパーの線
  const STEP = 4;          // ジッパーの線の点の間隔（px）。歯は1点ごとに左右交互に付く
  const SPREAD = 1.2;      // 開く幅の大きさ（開いた部分の真ん中で「開いた長さ × SPREAD ÷ 4」の幅になる）
  const CURVE_GAP = 8;     // なぞった点をこの間隔（px）より近いものは間引いてから曲線でつなぐ（大きいほど滑らか、細かい形は消える）
  const SMOOTH = 3;        // 曲線でつないだあと、さらにならす回数（多いほど手ぶれが消える）
  const MIN_LEN = 60;      // これより短くなぞった線はジッパーにしない（px）
  // 部品の大きさ（px）
  const TOOTH_W = 6;       // 歯の長さ（線と直角の向き）
  const TOOTH_H = 4;       // 歯の幅（線に沿った向き）
  const TOOTH_D = 2.5;     // 歯の厚み
  const TAPE_W = 5;        // 歯を縫い付けている布の幅
  const S = 12;            // 引き手の本体の長さの半分（線に沿った向き）
  const SLIDER_HW = 8;     // 引き手の本体の幅の半分（開いている側の端。本体はここが一番広い）
  const SLIDER_TAPER = 0.8;   // 本体の閉じている側の端の幅の割合（開いている側から先細りにする）
  // 本物のジッパーと同じく、左右の歯は離れたまま本体の広い端から入り、本体の中で噛み合う
  // （開いた所のV字の先は本体の中に隠れる。本体の手前で閉じきってはいけない）
  const SLIDER_GAP = 3.5;   // 本体の広い端から入る所での、左右の歯の間の半分（px）
  const GAP_RAMP = 24;     // 開け始めはこの長さ（px）開くまでに SLIDER_GAP まで広げる（開け始めに急に広がらないように）
  const MESH_IN = 1.4;     // 本体の広い端から、本体の長さの半分×この値だけ入った所で噛み合いきる
  const SLIDER_D = 7;      // 引き手の本体の厚み
  const TAB_H = 40;        // 引き手のつまみ（板）の長さ（根元の端から先まで）
  const TAB_W = 17;        // 引き手のつまみの幅
  // 垂れている部分は、本体の上の小さなアーチ（つなぎの輪）に根元を通して、本体の上に寝かせる
  // 引き手は「本体」と「つまみ」の2つの部品でできている。
  // 本体の上面には、線に沿った向きに渡した小さな橋（ブリッジ）があり、前後2本の脚で本体に立っている。
  // つまみは根元の近くに穴があり、その穴に橋の前の脚を通して、根元の端は橋の下にくぐらせる
  // （つまみの根元が橋の横棒をぐるりと囲む＝輪になってつながる）。つまみは本体の上に寝て閉じている側へ倒れる
  const BRIDGE_X0 = -S + 1; // 橋の後ろ（開いている側）の端の位置（本体の中心から線に沿った距離）
  const BRIDGE_L = 11;      // 橋の長さ（線に沿った向き）
  const BRIDGE_W = 5;       // 橋の幅
  const BRIDGE_H = 5.5;     // 橋の高さ（本体の上面から）
  const BRIDGE_T = 1.6;     // 橋の横棒と脚の太さ
  const TAB_ROOT = BRIDGE_X0 + BRIDGE_T + 1;  // つまみの根元の端（橋の後ろの脚のすぐ前、横棒の下）
  const SLOT_GAP = 0.7;     // つまみの穴と、そこを通る橋の脚とのすき間
  const TAB_D = 3;         // 引き手の垂れている部分の厚み
  const SLIDER_R = 6;      // 引き手の角の丸み
  const TOOTH_R = 1.2;     // 歯の角の丸み
  // 噛み合っている所は、左右の歯が一列に並んだ梯子のように見せる
  const MESH_LEN = STEP - 0.9;       // 噛み合った歯の長さ（線に沿った向き）。STEPとの差が歯の間のすき間になる
  const MESH_W = (TOOTH_W - 2) * 2;  // 噛み合った歯の幅（左右の歯を合わせた幅）
  const MESH_SHIFT = 0.6;            // 噛み合った歯を左右交互にずらす量（px）。完全に一直線にせず、わずかに互い違いにする
  const MESH_BLEND = 3;              // 開き幅の半分がこの値（px）になるまでに、噛み合った形から左右の歯へ移る
  const HOLE_L = 12;       // つまみの先の方に開ける窓の長さ
  const HOLE_W = 7;        // 同じく窓の幅
  const BODY_SHADE = 0.82; // 本体を垂れている部分よりこの割合だけ暗くする（重なっても見分けられるように）
  const SHAKE = 1.2;       // 引き手を動かしている間に震える幅（px）
  const SHAKE_ROT = 0.06;  // 同じく震えて傾く角度（ラジアン）
  const SHAKE_HOLD = 80;   // 指が止まってからも震えを続ける時間（ミリ秒）
  // 立体の見え方
  const CELL = 5;          // 外の写真の網目の細かさ（px）。小さいほど縁のめくれが滑らかだが重い
  // 外の写真は引き伸ばさず、開いた所を切り抜くだけ。切れ目の縁だけを少し手前にめくり上げる
  const LIP_W = 24;        // 縁がめくれ上がる幅（切れ目からの距離、px）
  const LIFT = 0.15;       // 縁が持ち上がる高さ（開き幅の半分に対する割合）
  const LIP_MAX = 14;      // 縁が持ち上がる高さの上限（px）
  const DEPTH = 120;       // 中の写真がどれだけ奥にあるか（px）
  const FOV = 30;          // カメラの画角（度）。大きいほど遠近感が強い
  const AMBIENT = 0.55;    // 光の当たらない向きの面の明るさ（0〜1）
  const LIGHT_DIR = [-0.15, 0.2, 1];  // 光の来る向き（左上の手前から）
  const FADE_W = 13;      // 開いた所の縁から内側へかける黒いフェードの幅（px）
  const FADE_ALPHA = 0.45; // 縁でのフェードの濃さ（0〜1）
  // 効果音
  const SE_VOLUME = 0.5;   // 全体の音量
  const PITCH_RISE = 1;    // 引き手が終わりに近づくほど音を高くする量（オクターブ。1で終わりの端が始まりの2倍の高さ）
  const TICK_GAP = 0.008;  // 引き手のカチカチ音の最短間隔（秒）。速く動かしても鳴りすぎないように
  const FADE_OUT = 0.1;    // ジッパーを消したとき、消えるまでの時間（秒）。開いていた所もこの間に閉じる
  // 黄金のジッパー
  const GOLD_RATE = 0.01;  // ジッパーが黄金になる確率
  // 隠しコマンド（成功すると次に付けるジッパーが黄金になる）
  const SECRET_KEYS = '1029384756';   // PC：この順に数字キーを押す
  const CORNER_SIZE = 80;             // スマホ：画面の4隅のこの範囲（px）を同時に押さえる
  const CORNER_HOLD = 5;              // スマホ：4隅を押さえ続ける時間（秒）
  // 共有
  const SHARE_INSTANT = 0.5;   // 共有がこの秒数より早くキャンセル扱いで終わったら、共有シートは出ていなかったとみなす
  // 操作
  const GRAB = 16;         // 引き手をつかめる範囲の余裕（px）
  const SEARCH = 30;       // 引き手を動かすとき、今の位置から前後何点までを探すか（線が交差していても飛ばないように）
  const KEY_STEP = 20;     // 矢印キー1回で引き手が動く量（px）
  const DEL_R = 16;        // 削除するとき、ジッパーの線（開いた部分はその幅）からこの距離までのタップで消す（px）

  // ---------- 準備 ----------
  const $ = id => document.getElementById(id);
  const cv = $('cv');
  const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  const COL = {
    front: css('--front'), back: css('--back'),
    tape: css('--tape'), tooth: css('--tooth'), slider: css('--slider'),
    delTape: css('--del-tape'), delTooth: css('--del-tooth'), delSlider: css('--del-slider'),
    goldTooth: css('--gold-tooth'), goldSlider: css('--gold-slider'),
  };

  let W = 0, H = 0, dpr = 1;
  const imgs = [null, null];  // 0: 外の写真, 1: 中の写真
  const layers = [document.createElement('canvas'), document.createElement('canvas')];

  const zippers = [];  // 付けたジッパー {pts:線の点, nx,ny:各点の法線, p:引き手の位置（始点からの長さ）, inf:縁のめくれ}
  let drawing = null;  // なぞっている途中の線 {id, raw}
  let drag = null;     // 引き手をつかんでいる指 {id, z, off}
  let active = null;   // 最後に作った・動かしたジッパー（矢印キーで動かす対象）
  let deleteMode = false;
  let nextGold = false;
  const fading = [];       // 消している途中のジッパー {zs:[ジッパー], start, parts}    // 隠しコマンドで、次に付けるジッパーを黄金にする  // オンの間はタップしたジッパーを消す（なぞっても付けない）

  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

  // ---------- 3Dの場面 ----------
  // 画面の1pxが、手前の写真の面（z=0）でちょうど1になるようにカメラを置く
  const renderer = new THREE.WebGLRenderer({ canvas: cv, antialias: true });
  renderer.setClearColor(css('--bg'));
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(FOV, 1, 1, 10000);

  scene.add(new THREE.AmbientLight(0xffffff, AMBIENT));
  const L = new THREE.Vector3(...LIGHT_DIR).normalize();
  const sun = new THREE.DirectionalLight(0xffffff, (1 - AMBIENT) / L.z);  // 正面を向いた面がちょうど元の写真の明るさになる
  sun.position.copy(L).multiplyScalar(2000);
  scene.add(sun, sun.target);

  const texs = layers.map(c => {
    const t = new THREE.CanvasTexture(c);
    t.minFilter = THREE.LinearFilter;
    t.generateMipmaps = false;
    return t;
  });

  // 写真の層：層0が一番手前（外の写真）。層kは DEPTH×k だけ奥にあり、偶数は外・奇数は中の写真。
  // ジッパーは開いた所から見えている層に付き、開くとさらに奥の層が見える
  // （外の写真に付けたジッパーの中にジッパーを付けると、また外の写真が見える）
  let D = 1;  // カメラから層0までの距離
  const scaleAt = k => (D + k * DEPTH) / D;  // 層kを画面いっぱいに見せるための拡大率

  // 切り抜き用の画像（白：残す、黒：抜く）
  function makeMask(){
    const c = document.createElement('canvas');
    const t = new THREE.CanvasTexture(c);
    t.minFilter = THREE.LinearFilter;
    t.generateMipmaps = false;
    return { c, g: c.getContext('2d'), t };
  }
  const sizeMask = m => {
    m.c.width = Math.max(1, Math.round(W * dpr));
    m.c.height = Math.max(1, Math.round(H * dpr));
  };

  // 層1より奥は平らな板（必要な数だけ作る）。
  // 板のすぐ手前に、一つ手前の層の開いた所の縁を黒くフェードさせる透明な板（shade）を重ねる
  const planes = [null];
  const SHADE_GAP = 0.3;  // フェードの板を写真の板からどれだけ手前に置くか
  function layoutPlane(k){
    const s = scaleAt(k), p = planes[k];
    p.mesh.position.z = -k * DEPTH;
    p.mesh.scale.set(W * s, H * s, 1);
    const ss = (D + k * DEPTH - SHADE_GAP) / D;  // 手前にある分だけ小さくして、画面上で写真とぴったり重ねる
    p.shadeMesh.position.z = -k * DEPTH + SHADE_GAP;
    p.shadeMesh.scale.set(W * ss, H * ss, 1);
  }
  function ensurePlanes(n){
    while (planes.length <= n){
      const k = planes.length, m = makeMask(), sh = makeMask();
      sizeMask(m); sizeMask(sh);
      const mat = new THREE.MeshLambertMaterial({ map: texs[k % 2], alphaMap: m.t, transparent: true, alphaTest: 0.01 });
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), mat);
      const shadeMat = new THREE.MeshBasicMaterial({ map: sh.t, alphaMap: m.t, transparent: true, depthWrite: false });
      const shadeMesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), shadeMat);
      scene.add(mesh, shadeMesh);
      planes.push({ ...m, mesh, shade: sh, shadeMesh });
      layoutPlane(k);
    }
    for (let k = 1; k < planes.length; k++){
      planes[k].mesh.visible = k <= n;
      planes[k].shadeMesh.visible = k <= n;
    }
  }

  // 一つ手前の層（k-1）の開いた所の縁に沿って、内側へ黒いフェードを描く
  // （幅の違う線を薄く重ね、縁ほど濃くなるようにする。canvasのぼかしは使えない環境があるため使わない）
  const FADE_STEPS = 6;
  function drawShade(k){
    const sh = planes[k].shade, g = sh.g;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, sh.c.width, sh.c.height);
    g.setTransform(sh.c.width / W, 0, 0, sh.c.height / H, 0, 0);
    g.lineJoin = 'round';
    const a = 1 - Math.pow(1 - FADE_ALPHA, 1 / FADE_STEPS);  // 全部重なった縁でちょうど FADE_ALPHA になる濃さ
    g.strokeStyle = `rgba(0,0,0,${a})`;
    // 消している途中のジッパーの分は、残っている度合いに合わせて薄くする
    for (const [z, alive] of [...zippers.map(z => [z, 1]), ...fadingZips()]){
      if (z.level !== k - 1 || !holePath(g, z)) continue;
      g.save();
      g.globalAlpha = alive;
      g.clip();  // 開いた所の内側だけに描く
      for (let i = 1; i <= FADE_STEPS; i++){
        g.lineWidth = FADE_W * 2 * i / FADE_STEPS;
        g.stroke();
      }
      g.restore();
    }
    sh.t.needsUpdate = true;
  }

  // 層0：外の写真（縁をめくるために網目にしてある）
  const front = makeMask();
  // 開いた所は半透明でも描けるようにする（消すときに開いた所をフェードで閉じるため）。
  // 完全に透明な所は捨てて、奥のものを隠さないようにする
  const frontMat = new THREE.MeshLambertMaterial({ map: texs[0], alphaMap: front.t, transparent: true, alphaTest: 0.01 });
  const maskOf = k => k === 0 ? front : planes[k];
  let frontGeo = new THREE.BufferGeometry();
  const frontMesh = new THREE.Mesh(frontGeo, frontMat);
  frontMesh.frustumCulled = false;
  scene.add(frontMesh);

  // 部品
  // 色はジッパーごとに付ける（材質は白にして、歯・引き手は1個ずつの色、布は頂点の色で塗る）
  const toothMat = new THREE.MeshLambertMaterial({ color: 0xffffff });
  const sliderMat = new THREE.MeshLambertMaterial({ color: 0xffffff });
  // 布は外の写真のすぐ上に重なるので、常に手前に描かれるようにずらす
  const tapeMat = new THREE.MeshLambertMaterial({
    color: 0xffffff, vertexColors: true, side: THREE.DoubleSide,
    polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
  });
  // 色の組：ふつう・黄金・削除がオンのとき（削除がオンの間はどれも赤くする）
  const palette = (tape, tooth, slider) => ({
    tape: new THREE.Color(tape), tooth: new THREE.Color(tooth), slider: new THREE.Color(slider),
    body: new THREE.Color(slider).multiplyScalar(BODY_SHADE),
  });
  const PAINT = {
    normal: palette(COL.tape, COL.tooth, COL.slider),
    gold: palette(COL.tape, COL.goldTooth, COL.goldSlider),
    del: palette(COL.delTape, COL.delTooth, COL.delSlider),
  };
  const paintOf = z => deleteMode ? PAINT.del : z.gold ? PAINT.gold : PAINT.normal;
  function makeInst(geo, mat, cap){
    const m = new THREE.InstancedMesh(geo, mat, cap);
    // 1個ずつの色は最初から用意しておく（後から足すと色を使う描き方に切り替わらないため）
    m.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(cap * 3).fill(1), 3);
    m.frustumCulled = false;
    m.count = 0;
    scene.add(m);
    return m;
  }
  // 数が足りなくなったら作り直す
  function fitInst(m, need){
    if (need > m.instanceMatrix.count){
      scene.remove(m);
      if (m.dispose) m.dispose();
      m = makeInst(m.geometry, m.material, Math.max(need, m.instanceMatrix.count * 2));
    }
    m.count = need;
    return m;
  }
  // 角を丸めた板（上から見た角を丸め、縁も少し面取りする）。hole を渡すとその形の穴を開ける
  function roundRectPath(p, x, y, w, h, r){
    r = Math.min(r, w / 2, h / 2);
    p.moveTo(x + r, y);
    p.lineTo(x + w - r, y); p.quadraticCurveTo(x + w, y, x + w, y + r);
    p.lineTo(x + w, y + h - r); p.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    p.lineTo(x + r, y + h); p.quadraticCurveTo(x, y + h, x, y + h - r);
    p.lineTo(x, y + r); p.quadraticCurveTo(x, y, x + r, y);
    return p;
  }
  // 角を丸めた多角形（凸形）。各角の手前と先 r の所を曲線でつなぐ
  function roundPolyPath(p, pts, r){
    const n = pts.length;
    for (let i = 0; i < n; i++){
      const c = pts[i], a = pts[(i + n - 1) % n], b = pts[(i + 1) % n];
      const da = Math.hypot(a.x - c.x, a.y - c.y), db = Math.hypot(b.x - c.x, b.y - c.y);
      const ra = Math.min(r, da / 2), rb = Math.min(r, db / 2);
      const x1 = c.x + (a.x - c.x) / da * ra, y1 = c.y + (a.y - c.y) / da * ra;
      if (i) p.lineTo(x1, y1); else p.moveTo(x1, y1);
      p.quadraticCurveTo(c.x, c.y, c.x + (b.x - c.x) / db * rb, c.y + (b.y - c.y) / db * rb);
    }
    p.closePath();
    return p;
  }
  // 平面の形を厚み d の板にする（縁を bevel だけ面取りする）
  function extrudeShape(shape, d, bevel){
    const depth = d - bevel * 2;
    const g = new THREE.ExtrudeGeometry(shape, {
      depth, curveSegments: 4,
      bevelEnabled: bevel > 0, bevelThickness: bevel, bevelSize: bevel, bevelSegments: 2,
    });
    g.translate(0, 0, -depth / 2);  // 厚みの中心を原点にする
    return g;
  }
  function roundedBox(w, h, d, r, bevel, hole){
    // 面取りの分だけ外側に膨らむので、元の形はその分小さく作る
    const shape = roundRectPath(new THREE.Shape(), -w / 2 + bevel, -h / 2 + bevel, w - bevel * 2, h - bevel * 2, Math.max(0.1, r - bevel));
    if (hole) shape.holes.push(hole);
    return extrudeShape(shape, d, bevel);
  }
  // 引き手の垂れている部分の先の方に、細長い穴を開ける
  const tabHole = roundRectPath(new THREE.Path(), TAB_H / 2 - 4 - HOLE_L, -HOLE_W / 2, HOLE_L, HOLE_W, 1.5);
  // 橋の前の脚を通す穴（つまみの中心から見た位置に直す）
  const tabSlot = (() => {
    const tabCenter = TAB_ROOT + TAB_H / 2;
    const legX = BRIDGE_X0 + BRIDGE_L - BRIDGE_T - SLOT_GAP - tabCenter;
    const w = BRIDGE_T + SLOT_GAP * 2, h = BRIDGE_W + SLOT_GAP * 2;
    return roundRectPath(new THREE.Path(), legX, -h / 2, w, h, 0.6);
  })();
  const toothGeo = roundedBox(TOOTH_H, TOOTH_W, TOOTH_D, TOOTH_R, 0.4);
  // 本体：開いている側（-x）が広く、閉じている側（+x）へ先細りになる台形
  const bodyGeo = (() => {
    const b = 1.2, hw0 = SLIDER_HW - b, hw1 = SLIDER_HW * SLIDER_TAPER - b, l = S - b;
    const pts = [{ x: -l, y: -hw0 }, { x: l, y: -hw1 }, { x: l, y: hw1 }, { x: -l, y: hw0 }];
    return extrudeShape(roundPolyPath(new THREE.Shape(), pts, SLIDER_R - b), SLIDER_D, b);
  })();
  const tabGeo = (() => {
    const b = 0.8;
    const shape = roundRectPath(new THREE.Shape(), -TAB_H / 2 + b, -TAB_W / 2 + b, TAB_H - b * 2, TAB_W - b * 2, SLIDER_R - b);
    shape.holes.push(tabHole, tabSlot);
    return extrudeShape(shape, TAB_D, b);
  })();
  // 本体の上の橋：横から見て「冂」の形を幅の向きに伸ばした部品（本体の上面が z=0、本体の中心が x=0）
  const bailGeo = (() => {
    const L = BRIDGE_L, Hh = BRIDGE_H, T = BRIDGE_T;
    const pts = [[0, 0], [0, Hh], [L, Hh], [L, 0], [L - T, 0], [L - T, Hh - T], [T, Hh - T], [T, 0]];
    const shape = new THREE.Shape(pts.map(([x, y]) => new THREE.Vector2(x, y)));
    const g = new THREE.ExtrudeGeometry(shape, { depth: BRIDGE_W, bevelEnabled: false });
    g.rotateX(Math.PI / 2);                        // 形の上下（y）を高さ（z）にし、伸ばした向きを幅（y）にする
    g.translate(BRIDGE_X0, BRIDGE_W / 2, 0);       // 幅の中心を線の上に、後ろの端を BRIDGE_X0 に置く
    return g;
  })();
  // 歯・布・引き手のひとそろい（ふだん描く分と、消している途中の分で別々に持つ）
  function makeParts(mats){
    const tape = new THREE.Mesh(new THREE.BufferGeometry(), mats.tape);
    tape.frustumCulled = false;
    scene.add(tape);
    return {
      mats, tape,
      teeth: makeInst(toothGeo, mats.tooth, 1024),
      body: makeInst(bodyGeo, mats.slider, 16),
      tab: makeInst(tabGeo, mats.slider, 16),
      bail: makeInst(bailGeo, mats.slider, 16),
    };
  }
  function disposeParts(P){
    for (const m of [P.teeth, P.body, P.tab, P.bail]){ scene.remove(m); if (m.dispose) m.dispose(); }
    scene.remove(P.tape);
    P.tape.geometry.dispose();
    for (const m of Object.values(P.mats)) m.dispose();
  }
  const mainParts = makeParts({ tooth: toothMat, slider: sliderMat, tape: tapeMat });

  // ---------- 外の写真の網目 ----------
  let cols = 1, rows = 1, cw = 1, ch = 1;
  let bx, by, basePos, bestD2, bestI, lipZ;
  function buildGrid(){
    cols = Math.max(1, Math.round(W / CELL));
    rows = Math.max(1, Math.round(H / CELL));
    cw = W / cols; ch = H / rows;
    const nv = (cols + 1) * (rows + 1);
    bx = new Float32Array(nv); by = new Float32Array(nv);
    basePos = new Float32Array(nv * 3);
    const uv = new Float32Array(nv * 2);
    for (let r = 0; r <= rows; r++){
      for (let c = 0; c <= cols; c++){
        const v = r * (cols + 1) + c, x = c * cw, y = r * ch;
        bx[v] = x; by[v] = y;
        basePos[v * 3] = x - W / 2; basePos[v * 3 + 1] = H / 2 - y;
        uv[v * 2] = x / W; uv[v * 2 + 1] = 1 - y / H;
      }
    }
    frontGeo.dispose();
    frontGeo = new THREE.BufferGeometry();
    const pos = new THREE.BufferAttribute(basePos.slice(), 3);
    pos.setUsage(THREE.DynamicDrawUsage);
    frontGeo.setAttribute('position', pos);
    frontGeo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    const idx = new Uint32Array(cols * rows * 6);
    let t = 0;
    for (let r = 0; r < rows; r++){
      for (let c = 0; c < cols; c++){
        const a = r * (cols + 1) + c, b = a + 1, e = a + cols + 1, d = e + 1;
        idx[t++] = a; idx[t++] = e; idx[t++] = b;
        idx[t++] = b; idx[t++] = e; idx[t++] = d;
      }
    }
    frontGeo.setIndex(new THREE.BufferAttribute(idx, 1));
    frontMesh.geometry = frontGeo;
    bestD2 = new Float32Array(nv).fill(Infinity);
    bestI = new Int32Array(nv);
    lipZ = new Float32Array(nv);
    for (const z of zippers) z.infP = null;  // 網目が変わったので縁のめくれを計算し直す
  }

  // ---------- 写真を画面サイズに合わせて下描きしておく ----------
  function renderLayer(i){
    const c = layers[i], g = c.getContext('2d');
    c.width = Math.max(1, Math.round(W * dpr));
    c.height = Math.max(1, Math.round(H * dpr));
    g.fillStyle = i === 0 ? COL.front : COL.back;
    g.fillRect(0, 0, c.width, c.height);
    if (cam.layer === i && drawVideo(c, g)){ texs[i].needsUpdate = true; return; }
    const im = imgs[i];
    if (im){
      // 画面いっぱいに収まるよう拡大し、はみ出た分は切る
      const s = Math.max(c.width / im.width, c.height / im.height);
      const w = im.width * s, h = im.height * s;
      g.drawImage(im, (c.width - w) / 2, (c.height - h) / 2, w, h);
    }
    texs[i].needsUpdate = true;
  }

  function resize(){
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    W = cv.clientWidth; H = cv.clientHeight;
    if (!W || !H) return;
    renderer.setPixelRatio(dpr);
    renderer.setSize(W, H, false);
    D = (H / 2) / Math.tan(FOV * Math.PI / 360);
    camera.aspect = W / H;
    camera.position.set(0, 0, D);
    camera.near = D * 0.5;
    // 奥の層は、奥にある分だけ大きくして画面いっぱいに見えるようにする
    sizeMask(front);
    for (let k = 1; k < planes.length; k++){ sizeMask(planes[k]); sizeMask(planes[k].shade); layoutPlane(k); }
    buildGrid();
    renderLayer(0); renderLayer(1);
    draw();
  }

  // ---------- 線の形 ----------
  // 線を STEP 間隔の点に並べ直す（歯を等間隔に付けるため）
  function resample(pts){
    const out = [{ x: pts[0].x, y: pts[0].y }];
    let rest = STEP;  // 次の点までの残りの長さ
    for (let i = 1; i < pts.length; i++){
      let ax = pts[i - 1].x, ay = pts[i - 1].y;
      const bxx = pts[i].x, byy = pts[i].y;
      let seg = Math.hypot(bxx - ax, byy - ay);
      while (seg >= rest){
        const t = rest / seg;
        ax += (bxx - ax) * t; ay += (byy - ay) * t;
        out.push({ x: ax, y: ay });
        seg -= rest; rest = STEP;
      }
      rest -= seg;
    }
    return out;
  }

  // 手ぶれをならす
  function smooth(pts){
    for (let k = 0; k < SMOOTH; k++){
      const q = pts.map(p => ({ x: p.x, y: p.y }));
      for (let i = 1; i < pts.length - 1; i++){
        q[i].x = (pts[i - 1].x + pts[i].x * 2 + pts[i + 1].x) / 4;
        q[i].y = (pts[i - 1].y + pts[i].y * 2 + pts[i + 1].y) / 4;
      }
      pts = q;
    }
    return pts;
  }

  // なぞった点を、間引いてから曲線（セントリペタル Catmull-Rom）でつなぐ。
  // 素早くなぞって点がまばらでも折れ線にならず、間隔がばらばらでも曲線が輪になったり尖ったりしない
  function curveThrough(raw){
    const pts = [raw[0]];
    for (const p of raw){
      const q = pts[pts.length - 1];
      if (Math.hypot(p.x - q.x, p.y - q.y) >= CURVE_GAP) pts.push(p);
    }
    const end = raw[raw.length - 1], q = pts[pts.length - 1];
    if (Math.hypot(end.x - q.x, end.y - q.y) > 1) pts.push(end);
    if (pts.length < 3) return pts;

    const out = [];
    const knot = (a, b) => Math.max(1e-4, Math.sqrt(Math.hypot(b.x - a.x, b.y - a.y)));
    const lerp = (a, b, ta, tb, t) => {
      const u = (t - ta) / (tb - ta);
      return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u };
    };
    for (let i = 0; i < pts.length - 1; i++){
      const p1 = pts[i], p2 = pts[i + 1];
      const p0 = pts[i - 1] || { x: 2 * p1.x - p2.x, y: 2 * p1.y - p2.y };   // 端は延長した点を補う
      const p3 = pts[i + 2] || { x: 2 * p2.x - p1.x, y: 2 * p2.y - p1.y };
      const t0 = 0, t1 = t0 + knot(p0, p1), t2 = t1 + knot(p1, p2), t3 = t2 + knot(p2, p3);
      const k = Math.max(1, Math.ceil(Math.hypot(p2.x - p1.x, p2.y - p1.y) / 2));  // 2pxごとに点を打つ
      for (let j = 0; j < k; j++){
        const t = t1 + (t2 - t1) * j / k;
        const a1 = lerp(p0, p1, t0, t1, t), a2 = lerp(p1, p2, t1, t2, t), a3 = lerp(p2, p3, t2, t3, t);
        const b1 = lerp(a1, a2, t0, t2, t), b2 = lerp(a2, a3, t1, t3, t);
        out.push(lerp(b1, b2, t1, t2, t));
      }
    }
    out.push(pts[pts.length - 1]);
    return out;
  }

  // なぞった点からジッパーの線を作る（なぞっている最中の表示と、指を離したときで同じ形にする）
  const buildPath = raw => resample(smooth(resample(curveThrough(raw))));

  // 各点の法線（線と直角の向き）。画面上の接線は (ny, -nx)
  function normals(pts){
    const n = pts.length, nx = new Float32Array(n), ny = new Float32Array(n);
    for (let i = 0; i < n; i++){
      const a = pts[Math.max(0, i - 2)], b = pts[Math.min(n - 1, i + 2)];
      let tx = b.x - a.x, ty = b.y - a.y;
      const l = Math.hypot(tx, ty) || 1;
      tx /= l; ty /= l;
      nx[i] = -ty; ny[i] = tx;
    }
    return { nx, ny };
  }

  // level：付いている層、parent：そのジッパーを付けた開き口のジッパー（層0なら無し）
  // gold：黄金のジッパーか
  const makeZipper = (pts, level = 0, parent = null, gold = false) => ({ pts, ...normals(pts), p: S, infP: null, inf: null, level, parent, gold });
  const lenOf = z => (z.pts.length - 1) * STEP;
  const sliderIndex = z => clamp(Math.round(z.p / STEP), 0, z.pts.length - 1);

  // i番目の点での開き幅の半分（始点と引き手の両端が閉じた目の形に開く）
  // O：始まりの端から本体の広い端までの長さ。始まりの端（閉じている）から広がり、本体の広い端では
  // SLIDER_GAP だけ離れたまま本体に入り、本体の中で 0 になる（噛み合う）
  function halfAt(z, i){
    const O = z.p - S, s = i * STEP;
    if (O <= 0) return 0;
    const g = SLIDER_GAP * Math.min(1, O / GAP_RAMP);
    if (s <= O){
      const u = s / O;
      return SPREAD * s * (O - s) / O / 2 + g * u * u;
    }
    const t = (s - O) / (S * MESH_IN);
    return t < 1 ? g * (1 - t) : 0;
  }

  // 開き幅の半分が h の所で、切れ目から e だけ外側の布の高さ（切れ目より内側は縁と同じ高さ）
  function zAt(h, e){
    const top = Math.min(LIP_MAX, LIFT * h);
    if (top <= 0 || e >= LIP_W) return 0;
    if (e <= 0) return top;
    const t = 1 - e / LIP_W;
    return top * t * t;
  }

  // ---------- 縁のめくれ ----------
  // 網目の各点の、一番近いジッパーの点から見た高さを求める（引き手を動かしたジッパーだけ計算し直す）
  function computeInfluence(z){
    z.infP = z.p; z.inf = null;
    if (z.p - S <= 0) return;
    const touched = [];
    for (let i = 0; i < z.pts.length; i++){
      const h = halfAt(z, i), R = h + LIP_W, R2 = R * R, p = z.pts[i];
      const c0 = Math.max(0, Math.floor((p.x - R) / cw)), c1 = Math.min(cols, Math.ceil((p.x + R) / cw));
      const r0 = Math.max(0, Math.floor((p.y - R) / ch)), r1 = Math.min(rows, Math.ceil((p.y + R) / ch));
      for (let r = r0; r <= r1; r++){
        let v = r * (cols + 1) + c0;
        for (let c = c0; c <= c1; c++, v++){
          const dx = bx[v] - p.x, dy = by[v] - p.y, d2 = dx * dx + dy * dy;
          if (d2 < R2 && d2 < bestD2[v]){
            if (bestD2[v] === Infinity) touched.push(v);
            bestD2[v] = d2; bestI[v] = i;
          }
        }
      }
    }
    const m = touched.length;
    const f = { idx: new Int32Array(m), z: new Float32Array(m), n: 0 };
    for (const v of touched){
      const i = bestI[v];
      bestD2[v] = Infinity;
      const h = halfAt(z, i);
      if (h <= 0) continue;
      const p = z.pts[i], ex = bx[v] - p.x, ey = by[v] - p.y;
      // 線の真横にない点（本当に一番近い点が届かず、遠くの点に拾われただけの点）は動かさない
      if (Math.abs(ex * z.ny[i] - ey * z.nx[i]) > STEP) continue;
      const lat = Math.abs(ex * z.nx[i] + ey * z.ny[i]);  // 線からの横の距離
      const zz = zAt(h, lat - h);
      if (zz <= 0) continue;
      const k = f.n++;
      f.idx[k] = v; f.z[k] = zz;
    }
    z.inf = f;
  }

  // 開いた所の形（左右の切れ目をつないだ輪郭、画面の座標）
  function holePath(g, z){
    const O = z.p - S;
    if (O <= 0) return false;
    const n = Math.min(z.pts.length - 1, Math.ceil((O + S * MESH_IN) / STEP));  // 本体の中で噛み合う所まで
    g.beginPath();
    for (let i = 0; i <= n; i++){
      const h = halfAt(z, i), p = z.pts[i];
      const x = p.x + z.nx[i] * h, y = p.y + z.ny[i] * h;
      if (i) g.lineTo(x, y); else g.moveTo(x, y);
    }
    for (let i = n; i >= 0; i--){
      const h = halfAt(z, i), p = z.pts[i];
      g.lineTo(p.x - z.nx[i] * h, p.y - z.ny[i] * h);
    }
    g.closePath();
    return true;
  }

  // 画面の点で見えている層と、その点を開いているジッパー（手前の層から開き口をたどる）
  const probe = document.createElement('canvas').getContext('2d');
  function levelAt(x, y){
    let level = 0, parent = null;
    for (;;){
      const z = zippers.find(q => q.level === level && holePath(probe, q) && probe.isPointInPath(x, y));
      if (!z) return { level, parent };
      parent = z; level++;
    }
  }

  // 必要な層の数（一番奥のジッパーの層＋1）
  // 消している途中のジッパー（と、そのまだ残っている度合い 1→0）
  const fadingZips = () => {
    const now = performance.now(), out = [];
    for (const f of fading){
      const a = Math.max(0, 1 - (now - f.start) / (FADE_OUT * 1000));
      for (const z of f.zs) out.push([z, a]);
    }
    return out;
  };
  const deepest = () => [...zippers, ...fading.flatMap(f => f.zs)].reduce((n, z) => Math.max(n, z.level + 1), 1);

  function updateFront(){
    const n = deepest();
    ensurePlanes(n);
    camera.far = D + n * DEPTH + 10;   // 奥行きの範囲を必要な分だけに絞り、前後の判定の精度を上げる
    camera.updateProjectionMatrix();

    // 切り抜き：各層で、その層のジッパーが開いた所を黒く塗る
    for (let k = 0; k <= n; k++){
      const m = maskOf(k);
      m.g.setTransform(1, 0, 0, 1, 0, 0);
      m.g.fillStyle = '#fff';
      m.g.fillRect(0, 0, m.c.width, m.c.height);
      m.g.setTransform(m.c.width / W, 0, 0, m.c.height / H, 0, 0);
      // 消している途中の開き口は、残っている度合いに合わせて灰色で薄く抜く（だんだん閉じる）
      for (const [z, a] of fadingZips()){
        if (z.level !== k || !holePath(m.g, z)) continue;
        const v = Math.round(255 * (1 - a));
        m.g.fillStyle = `rgb(${v},${v},${v})`;
        m.g.fill();
      }
      m.g.fillStyle = '#000';
      for (const z of zippers) if (z.level === k && holePath(m.g, z)) m.g.fill();
      m.t.needsUpdate = true;
      if (k > 0) drawShade(k);
    }

    // 縁のめくれ（層0だけ）：ジッパーが重なる所は高い方を使う
    const pos = frontGeo.attributes.position.array;
    lipZ.fill(0);
    // 消している途中のジッパーのめくれは、残っている度合いに合わせて平らに戻す
    for (const [z, a] of [...zippers.map(z => [z, 1]), ...fadingZips()]){
      if (z.level !== 0) continue;
      if (z.infP !== z.p) computeInfluence(z);
      const f = z.inf;
      if (!f) continue;
      for (let j = 0; j < f.n; j++){
        const v = f.idx[j], h = f.z[j] * a;
        if (h > lipZ[v]) lipZ[v] = h;
      }
    }
    for (let v = 0; v < lipZ.length; v++) pos[v * 3 + 2] = lipZ[v];
    frontGeo.attributes.position.needsUpdate = true;
    frontGeo.computeVertexNormals();
  }

  // ---------- 歯・布・引き手 ----------
  const M = new THREE.Matrix4(), SC = new THREE.Vector3(), TS = new THREE.Vector3();
  function updateParts(){
    const list = zippers.map(z => [z, true]);
    // なぞっている途中は、閉じたジッパーとして見せる
    if (drawing && drawing.raw.length > 1){
      const pts = buildPath(drawing.raw);
      if (pts.length > 1) list.push([makeZipper(pts, drawing.level, null, drawing.gold), false]);
    }
    fillParts(mainParts, list);
  }

  // list（[ジッパー, 引き手を描くか]）の歯・布・引き手を P に並べる
  function fillParts(P, list){
    let nTeeth = 0, nSlider = 0;
    for (const [z, withSlider] of list){ nTeeth += z.pts.length; if (withSlider) nSlider++; }
    const teethInst = P.teeth = fitInst(P.teeth, nTeeth);
    const bodyInst = P.body = fitInst(P.body, nSlider);
    const tabInst = P.tab = fitInst(P.tab, nSlider);
    const bailInst = P.bail = fitInst(P.bail, nSlider);
    const tapeMesh = P.tape;

    const tapePos = new Float32Array(nTeeth * 4 * 3), tapeCol = new Float32Array(nTeeth * 4 * 3), tapeIdx = [];
    const outer = TOOTH_W - 2 + TAPE_W;  // 布は切れ目から歯の外側まで
    let ti = 0, tv = 0, si = 0;
    for (const [z, withSlider] of list){
      const n = z.pts.length, base = tv;
      // 付いている層の面に置く（奥の層ほど大きくして、画面上は同じ大きさ・位置に見せる）
      const s = scaleAt(z.level), z0 = -z.level * DEPTH, flat = z.level !== 0;
      const wx = x => (x - W / 2) * s, wy = y => (H / 2 - y) * s;
      SC.set(s, s, s);
      const paint = paintOf(z);
      for (let i = 0; i < n; i++){
        const p = z.pts[i], h = halfAt(z, i), nx = z.nx[i], ny = z.ny[i];
        const lip = flat ? 0 : zAt(h, 0);  // 縁がめくれるのは層0だけ
        const ang = Math.atan2(nx, ny);  // 3Dでの線の向き（画面の接線 (ny,-nx) を上下反転）
        // 歯（左右交互。中心は切れ目から少し内側にはみ出す）
        // 噛み合っている所（mesh=1）は線の真ん中に揃えて全幅にし、開くにつれて片側の歯の形と位置に移す
        const mesh = Math.max(0, 1 - h / MESH_BLEND);
        const o = (i % 2 === 0 ? 1 : -1) * ((1 - mesh) * (h + (TOOTH_W - 4) / 2) + mesh * MESH_SHIFT);
        const len = MESH_LEN + (TOOTH_H - MESH_LEN) * (1 - mesh);
        const wid = MESH_W + (TOOTH_W - MESH_W) * (1 - mesh);
        M.makeRotationZ(ang).scale(TS.set(s * len / TOOTH_H, s * wid / TOOTH_W, s));
        M.setPosition(wx(p.x + nx * o), wy(p.y + ny * o), z0 + lip + TOOTH_D / 2 * s);
        teethInst.setColorAt(ti, paint.tooth);
        teethInst.setMatrixAt(ti++, M);
        // 布（両側。内側の縁と外側の縁の2点ずつ）
        for (const sg of [1, -1]){
          for (const e of [0, outer]){
            const off = sg * (h + e);
            tapePos[tv * 3] = wx(p.x + nx * off);
            tapePos[tv * 3 + 1] = wy(p.y + ny * off);
            // 高さは切れ目の縁（布の一番高い所）に揃える。外側を写真の面に沿わせると写真が突き抜けてちらつくため
            tapePos[tv * 3 + 2] = z0 + lip + 0.5 * s;
            paint.tape.toArray(tapeCol, tv * 3);
            tv++;
          }
        }
      }
      for (let i = 0; i < n - 1; i++){
        const a = base + i * 4, b = a + 4;
        tapeIdx.push(a, a + 1, b, a + 1, b + 1, b);
        tapeIdx.push(a + 2, a + 3, b + 2, a + 3, b + 3, b + 2);
      }
      // 引き手（垂れている部分は閉じている側に向く）
      if (withSlider){
        const i = sliderIndex(z), p = z.pts[i], nx = z.nx[i], ny = z.ny[i];
        // 動かしている間は小刻みに震わせる（位置と傾きを毎回ばらつかせる）
        const shaking = performance.now() < (z.shakeUntil || 0);
        const jx = shaking ? (Math.random() * 2 - 1) * SHAKE : 0;
        const jy = shaking ? (Math.random() * 2 - 1) * SHAKE : 0;
        const ang = Math.atan2(nx, ny) + (shaking ? (Math.random() * 2 - 1) * SHAKE_ROT : 0);
        const tx = Math.cos(ang), ty = Math.sin(ang);  // 3Dでの引き手の向き
        M.makeRotationZ(ang).scale(SC);
        M.setPosition(wx(p.x + jx), wy(p.y + jy), z0 + (TOOTH_D + SLIDER_D / 2) * s);
        const top = z0 + (TOOTH_D + SLIDER_D) * s;   // 本体の上面の高さ
        bodyInst.setMatrixAt(si, M);
        bodyInst.setColorAt(si, paint.body);
        // 本体の上の橋（本体の一部なので本体と同じ色）
        M.setPosition(wx(p.x + jx), wy(p.y + jy), top - 0.2 * s);
        bailInst.setMatrixAt(si, M);
        bailInst.setColorAt(si, paint.body);
        // つまみ（根元を橋の下にくぐらせ、穴に橋の前の脚を通して、本体の上に寝かせて閉じている側へ伸ばす）
        const off = (TAB_ROOT + TAB_H / 2) * s;
        M.setPosition(wx(p.x + jx) + tx * off, wy(p.y + jy) + ty * off, top + (TAB_D / 2 + 0.3) * s);
        tabInst.setMatrixAt(si, M);
        tabInst.setColorAt(si, paint.slider);
        si++;
      }
    }
    for (const m of [teethInst, bodyInst, tabInst, bailInst]){
      m.instanceMatrix.needsUpdate = true;
      m.instanceColor.needsUpdate = true;
    }

    tapeMesh.geometry.dispose();
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(tapePos, 3));
    g.setAttribute('color', new THREE.BufferAttribute(tapeCol, 3));
    g.setIndex(tapeIdx);
    g.computeVertexNormals();
    tapeMesh.geometry = g;
  }

  // 消している途中のジッパーを薄くしていき、消え終わったら片付ける
  function updateFading(){
    const now = performance.now();
    for (let i = fading.length - 1; i >= 0; i--){
      const f = fading[i], a = 1 - (now - f.start) / (FADE_OUT * 1000);
      if (a <= 0){ disposeParts(f.parts); fading.splice(i, 1); continue; }
      for (const m of Object.values(f.parts.mats)) m.opacity = a;
    }
  }

  // 消したジッパーを、消している途中の分として残す（その時の見た目のまま固めて薄くしていく）
  function startFading(zs){
    const mats = { tooth: toothMat.clone(), slider: sliderMat.clone(), tape: tapeMat.clone() };
    for (const m of Object.values(mats)) m.transparent = true;
    const parts = makeParts(mats);
    for (const m of [parts.teeth, parts.body, parts.tab, parts.bail, parts.tape]) m.renderOrder = 1;  // 写真より後に重ねる
    fillParts(parts, zs.map(z => [z, true]));
    fading.push({ zs, start: performance.now(), parts });
  }

  function draw(){
    if (!W || !H) return;
    updateFading();
    updateFront();
    updateParts();
    renderer.render(scene, camera);
    if (fading.length) requestDraw();  // 消している途中は描き続ける
    // 震えている引き手がある間は描き続ける（震えが止まった後も少しだけ描き、止まった姿で終える）
    const now = performance.now();
    if (zippers.some(z => now < (z.shakeUntil || 0) + 50)) requestDraw();
  }

  let drawQueued = false;
  function requestDraw(){
    if (drawQueued) return;
    drawQueued = true;
    requestAnimationFrame(() => { drawQueued = false; draw(); });
  }

  function setP(z, v){
    const old = z.p, max = Math.max(S, lenOf(z) - S);
    z.p = clamp(v, S, max);
    const moved = z.p - old;
    if (moved){
      // 引き手が歯を1本越えるごとにカチッ、動かす速さに合わせてジーッという擦れる音
      const now = performance.now(), dt = Math.max(1, now - (z.lastMove || 0)) / 1000;
      z.lastMove = now;
      z.shakeUntil = now + SHAKE_HOLD;
      // 引き手の位置（0：始まりの端〜1：終わりの端）。終わりに近づくほど音を高くする
      const pos = max > S ? (z.p - S) / (max - S) : 0;
      se.zip(Math.abs(moved) / Math.min(dt, 0.1), moved > 0, pos);
      z.tick = (z.tick || 0) + Math.abs(moved);
      if (z.tick >= STEP){ z.tick %= STEP; se.tick(moved > 0, pos); }
      // 端まで来たら止め具に当たるカチン
      if ((z.p === S || z.p === max) && old !== z.p) se.stopper();
    }
    requestDraw();
  }

  // ---------- 効果音 ----------
  // 音声ファイルは使わず Web Audio で合成する。最初の操作で鳴らせる状態にする
  const se = (() => {
    let ac = null, out = null, burst = null, on = true, lastTick = 0;
    let zipGain = null, zipFilter = null;  // 引き手を動かしている間のジーッという音
    let rumbleGain = null;                  // 開くときだけ重ねる低いゴロゴロ（重み）
    const init = () => {
      if (ac) return;
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      ac = new AC();
      // 小さい音も聞こえ、重なっても割れないよう軽く圧縮してから出す
      const comp = ac.createDynamicsCompressor();
      comp.threshold.value = -18; comp.ratio.value = 4;
      out = ac.createGain();
      out.gain.value = SE_VOLUME;
      out.connect(comp).connect(ac.destination);
      // カチッの元になる短いノイズ
      burst = ac.createBuffer(1, Math.round(ac.sampleRate * 0.05), ac.sampleRate);
      const d = burst.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      // ジーッの元：ずっと流しておくノイズ（普段は音量0）
      const loop = ac.createBuffer(1, ac.sampleRate, ac.sampleRate);
      const l = loop.getChannelData(0);
      for (let i = 0; i < l.length; i++) l[i] = Math.random() * 2 - 1;
      const src = ac.createBufferSource();
      src.buffer = loop; src.loop = true;
      const hp = ac.createBiquadFilter();
      hp.type = 'highpass'; hp.frequency.value = 400;
      zipFilter = ac.createBiquadFilter();
      zipFilter.type = 'bandpass'; zipFilter.frequency.value = 3000; zipFilter.Q.value = 1.2;
      zipGain = ac.createGain();
      zipGain.gain.value = 0;
      src.connect(hp).connect(zipFilter).connect(zipGain).connect(out);
      const lp = ac.createBiquadFilter();
      lp.type = 'lowpass'; lp.frequency.value = 320; lp.Q.value = 0.7;
      rumbleGain = ac.createGain();
      rumbleGain.gain.value = 0;
      src.connect(lp).connect(rumbleGain).connect(out);
      src.start();
    };
    const unlock = () => {
      init();
      if (ac && ac.state !== 'running') ac.resume();
    };
    ['pointerdown', 'touchend', 'keydown'].forEach(t => document.addEventListener(t, unlock, true));
    const ready = () => on && ac && ac.state === 'running';

    // 金属のカチッ：帯域を絞ったノイズの粒に、ごく短い金属の響き（高いサイン波）を足す
    function click(freq, gain, len, ring = 0){
      const t = ac.currentTime;
      const src = ac.createBufferSource(), bp = ac.createBiquadFilter(), g = ac.createGain();
      src.buffer = burst;
      bp.type = 'bandpass'; bp.frequency.value = freq; bp.Q.value = 3;
      g.gain.setValueAtTime(gain, t);
      g.gain.exponentialRampToValueAtTime(0.0005, t + len);
      src.connect(bp).connect(g).connect(out);
      src.start(t); src.stop(t + len);
      if (ring){
        const o = ac.createOscillator(), rg = ac.createGain();
        o.type = 'sine'; o.frequency.value = ring;
        rg.gain.setValueAtTime(gain * 0.12, t);
        rg.gain.exponentialRampToValueAtTime(0.0005, t + len * 3);
        o.connect(rg).connect(out);
        o.start(t); o.stop(t + len * 3);
      }
    }
    // 音程が動く短い音
    function tone(type, f0, f1, gain, len, delay = 0){
      const t = ac.currentTime + delay;
      const o = ac.createOscillator(), g = ac.createGain();
      o.type = type;
      o.frequency.setValueAtTime(f0, t);
      o.frequency.exponentialRampToValueAtTime(f1, t + len);
      g.gain.setValueAtTime(0.0005, t);
      g.gain.exponentialRampToValueAtTime(gain, t + 0.005);
      g.gain.exponentialRampToValueAtTime(0.0005, t + len);
      o.connect(g).connect(out);
      o.start(t); o.stop(t + len);
    }
    // 帯域が動くノイズ（シュッ）
    function swish(f0, f1, gain, len){
      const t = ac.currentTime;
      const src = ac.createBufferSource(), bp = ac.createBiquadFilter(), g = ac.createGain();
      src.buffer = burst; src.loop = true;
      bp.type = 'bandpass'; bp.Q.value = 2;
      bp.frequency.setValueAtTime(f0, t);
      bp.frequency.exponentialRampToValueAtTime(f1, t + len);
      g.gain.setValueAtTime(0.0005, t);
      g.gain.exponentialRampToValueAtTime(gain, t + len * 0.3);
      g.gain.exponentialRampToValueAtTime(0.0005, t + len);
      src.connect(bp).connect(g).connect(out);
      src.start(t); src.stop(t + len);
    }

    return {
      setOn(v){
        on = v;
        if (!v && ac) for (const g of [zipGain, rumbleGain]){ g.gain.cancelScheduledValues(ac.currentTime); g.gain.setValueAtTime(0, ac.currentTime); }
      },
      // 引き手が歯を越えるカチッ（毎回少しばらつかせて機械的にしない）
      // 開くときは歯が噛み合いを外れる重い音：低めのコツッに、さらに低い胴鳴りを足す
      tick(opening, pos = 0){
        if (!ready() || ac.currentTime - lastTick < TICK_GAP) return;
        lastTick = ac.currentTime;
        const r = (0.85 + Math.random() * 0.3) * Math.pow(2, pos * PITCH_RISE);
        if (opening){
          click(1400 * r, 0.4 + Math.random() * 0.15, 0.035);
          tone('triangle', 230 * r, 140 * r, 0.28, 0.045);
        } else {
          const f = 3200 * r;
          click(f, 0.25 + Math.random() * 0.15, 0.018, f * 1.6);
        }
      },
      // 引き手を動かしている間のジーッ（速いほど大きく高く。止めるとすぐ消える）
      zip(speed, opening, pos = 0){
        if (!ready()) return;
        const t = ac.currentTime, k = Math.min(1, speed / 1200), up = Math.pow(2, pos * PITCH_RISE);
        // 開くときは擦れる音を低くし、低いゴロゴロを重ねて重みを出す
        zipFilter.frequency.setTargetAtTime((opening ? 900 + k * 900 : 2000 + k * 2400) * up, t, 0.02);
        zipGain.gain.cancelScheduledValues(t);
        zipGain.gain.setTargetAtTime(0.06 + k * 0.22, t, 0.01);
        zipGain.gain.setTargetAtTime(0, t + 0.06, 0.03);
        rumbleGain.gain.cancelScheduledValues(t);
        rumbleGain.gain.setTargetAtTime(opening ? 0.15 + k * 0.35 : 0, t, 0.015);
        rumbleGain.gain.setTargetAtTime(0, t + 0.06, 0.04);
      },
      // 端の止め具に当たるカチン
      stopper(){
        if (!ready()) return;
        click(2200, 0.6, 0.03, 3100);
      },
      // ジッパーを付けたときのカチャッ（金具が2回当たる）
      attach(){
        if (!ready()) return;
        click(2600, 0.6, 0.03, 3800);
        setTimeout(() => ready() && click(1900, 0.45, 0.04, 2900), 45);
      },
      // ジッパーを消したときのシュッ＋ポン
      remove(){
        if (!ready()) return;
        swish(5000, 900, 0.35, 0.18);
        tone('sine', 420, 110, 0.4, 0.16, 0.05);
      },
    };
  })();

  // ---------- 入力 ----------
  // 手前の写真の面は画面とぴったり重なるので、指の位置は画面のpxのままで扱える
  const localPos = e => {
    const r = cv.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };

  // 指の下にある引き手（その点で見えている層のものだけ。後から付けたものを優先）
  function hitSlider(x, y){
    const vis = levelAt(x, y).level;
    for (let k = zippers.length - 1; k >= 0; k--){
      const z = zippers[k];
      if (z.level !== vis) continue;
      const i = sliderIndex(z), p = z.pts[i];
      const dx = x - p.x, dy = y - p.y;
      const u = dx * z.ny[i] - dy * z.nx[i];   // 線の進む向きの距離
      const v = dx * z.nx[i] + dy * z.ny[i];   // 線と直角の向きの距離
      if (u > -S - GRAB && u < Math.max(S, TAB_ROOT + TAB_H) + GRAB && Math.abs(v) < SLIDER_HW + GRAB) return z;
    }
    return null;
  }

  // 指の下にあるジッパー（線・開いた部分・引き手のどこでもよい。後から付けたものを優先）
  // （見えている層より奥のものは除き、奥の層・後から付けたものを優先）
  function hitZipper(x, y){
    const vis = levelAt(x, y).level;
    const cand = zippers.map((z, k) => [z, k]).filter(([z]) => z.level <= vis)
      .sort((a, b) => b[0].level - a[0].level || b[1] - a[1]);
    for (const [z] of cand){
      for (let i = 0; i < z.pts.length; i++){
        const r = halfAt(z, i) + DEL_R;
        if ((z.pts[i].x - x) ** 2 + (z.pts[i].y - y) ** 2 < r * r) return z;
      }
    }
    return hitSlider(x, y);
  }

  // 消すときは、その開き口の中に付けたジッパーも一緒に消す
  function removeZipper(z){
    const dead = new Set([z]);
    for (let grew = true; grew;){
      grew = false;
      for (const q of zippers) if (!dead.has(q) && dead.has(q.parent)){ dead.add(q); grew = true; }
    }
    for (const q of dead) zippers.splice(zippers.indexOf(q), 1);
    startFading([...dead]);
    if (dead.has(active)) active = zippers[zippers.length - 1] || null;
    se.remove();
    if (deleteMode && !zippers.length) toggleDelete();  // 全部消したら削除モードを自動で解除する
    requestDraw();
  }

  // 指に一番近い線上の点（今の位置の前後だけを探す）
  function nearestIndex(z, x, y, around){
    let best = around, bd = Infinity;
    const a = Math.max(0, around - SEARCH), b = Math.min(z.pts.length - 1, around + SEARCH);
    for (let i = a; i <= b; i++){
      const d = (z.pts[i].x - x) ** 2 + (z.pts[i].y - y) ** 2;
      if (d < bd){ bd = d; best = i; }
    }
    return best;
  }

  function finishPath(){
    const d = drawing, raw = d.raw;
    drawing = null;
    if (raw.length > 1){
      const pts = buildPath(raw);
      if ((pts.length - 1) * STEP >= MIN_LEN){
        const z = makeZipper(pts, d.level, d.parent, d.gold);
        if (d.gold) nextGold = false;  // 隠しコマンドの黄金確定は1回だけ
        zippers.push(z);
        active = z;
        se.attach();
      }
    }
    requestDraw();
  }

  cv.addEventListener('pointerdown', e => {
    if (e.pointerType === 'touch' && cornerOf(e.clientX, e.clientY) >= 0) return;  // 隅に置いた指では操作を始めない（隠しコマンド用）
    if (drag || drawing) return;   // 操作は指1本ずつ
    const { x, y } = localPos(e);
    e.preventDefault();
    if (deleteMode){
      const z = hitZipper(x, y);
      if (z) removeZipper(z);
      return;
    }
    cv.setPointerCapture(e.pointerId);
    const z = hitSlider(x, y);
    if (z){
      // 引き手をつかむ（つかんだ所と引き手の中心のずれを保つ）
      const i = nearestIndex(z, x, y, sliderIndex(z));
      drag = { id: e.pointerId, z, off: i * STEP - z.p };
      active = z;
      cv.style.cursor = 'grabbing';
      return;
    }
    // それ以外の場所は、なぞってジッパーを付ける（なぞり始めの点で見えている層に付く）
    // 黄金になるかは、なぞり始めに決める（なぞっている最中から黄金で見せるため）
    drawing = { id: e.pointerId, raw: [{ x, y }], ...levelAt(x, y), gold: nextGold || Math.random() < GOLD_RATE };
  });
  cv.addEventListener('pointermove', e => {
    const { x, y } = localPos(e);
    if (drag && e.pointerId === drag.id){
      const z = drag.z;
      const i = nearestIndex(z, x, y, clamp(Math.round((z.p + drag.off) / STEP), 0, z.pts.length - 1));
      setP(z, i * STEP - drag.off);
      return;
    }
    if (drawing && e.pointerId === drawing.id){
      drawing.raw.push({ x, y });
      requestDraw();
      return;
    }
    if (e.pointerType === 'mouse'){
      cv.style.cursor = deleteMode ? (hitZipper(x, y) ? 'pointer' : '') : (hitSlider(x, y) ? 'grab' : '');
    }
  });
  const endPointer = (e, cancel) => {
    if (drag && e.pointerId === drag.id){ drag = null; cv.style.cursor = ''; }
    if (drawing && e.pointerId === drawing.id){
      if (cancel){ drawing = null; requestDraw(); } else finishPath();
    }
  };
  cv.addEventListener('pointerup', e => endPointer(e, false));
  cv.addEventListener('pointercancel', e => endPointer(e, true));

  // 削除トグル（タッチは連打の拡大防止に止められないよう pointerdown で、キーボード操作は click で切り替える）
  const delBtn = $('del');
  const toggleDelete = () => {
    deleteMode = !deleteMode;
    delBtn.setAttribute('aria-pressed', String(deleteMode));
    cv.style.cursor = '';
    requestDraw();
  };
  delBtn.addEventListener('pointerdown', e => { e.preventDefault(); toggleDelete(); });
  delBtn.addEventListener('click', e => { if (e.detail === 0) toggleDelete(); });

  // 効果音のオン・オフ（切り替え方は削除トグルと同じ）
  const soundBtn = $('sound');
  const toggleSound = () => {
    const v = soundBtn.getAttribute('aria-pressed') !== 'true';
    soundBtn.setAttribute('aria-pressed', String(v));
    se.setOn(v);
  };
  soundBtn.addEventListener('pointerdown', e => { e.preventDefault(); toggleSound(); });
  soundBtn.addEventListener('click', e => { if (e.detail === 0) toggleSound(); });

  // ---------- 共有 ----------
  const shareText = () => 'ジッパーで写真を開いた！\n' + new URL('./', location.href).href + '\n#ジッパーフィンガー';
  // 今の画面を画像にする（WebGLの描画は次の表示までしか残らないので、描き直した直後に写し取る）
  function snapshotCanvas(){
    draw();
    const c = document.createElement('canvas');
    c.width = cv.width; c.height = cv.height;
    c.getContext('2d').drawImage(cv, 0, 0);
    return c;
  }
  // 画像をPNGのファイルにする（共有シートの制約があるため同期処理で作る）
  function imageFile(c){
    const bin = atob(c.toDataURL('image/png').split(',')[1]);
    const buf = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
    return new File([buf], 'zipper.png', { type: 'image/png' });
  }
  const shareBtn = $('share'), shareView = $('share-view');
  shareBtn.addEventListener('pointerdown', e => e.stopPropagation());
  shareBtn.addEventListener('click', () => {
    const text = shareText();
    const c = snapshotCanvas();
    const file = imageFile(c);
    // 3) 共有シートが無い・使えない環境: 文面をコピーし、共有される内容（画像と文面）を画面に出す
    const fallback = () => {
      navigator.clipboard?.writeText(text).catch(() => {});
      $('share-img').src = c.toDataURL('image/png');
      $('share-text').textContent = text;
      shareView.classList.remove('hidden');
      $('share-close').focus({ preventScroll:true });
    };
    // 共有シートが出なかったときは 3) へ：失敗した（埋め込み表示で共有が禁止されている等）とき、
    // またはキャンセル扱いでも押してすぐ（SHARE_INSTANT 秒未満）に終わったとき（シートを出せないアプリ内ブラウザ等）。
    // 共有シートを開いてから自分で閉じたキャンセルでは何もしない
    const shareStart = performance.now();
    const failed = err => {
      const instant = performance.now() - shareStart < SHARE_INSTANT * 1000;
      if (!err || err.name !== 'AbortError' || instant) fallback();
    };
    // 1) 画像を渡せる共有シート（スマホなど）: 文面＋画像
    if (navigator.canShare && navigator.canShare({ files: [file] })){
      navigator.share({ text, files: [file] }).catch(failed);
      return;
    }
    // 2) 画像を渡せない共有シート: 文面のみ
    if (navigator.share){
      navigator.share({ text }).catch(failed);
      return;
    }
    fallback();
  });
  const shareViewOpen = () => !shareView.classList.contains('hidden');
  const closeShareView = () => {
    shareView.classList.add('hidden');
    shareBtn.focus({ preventScroll:true });
  };
  $('share-close').addEventListener('click', closeShareView);
  shareView.addEventListener('pointerdown', e => e.stopPropagation());

  // PCでは矢印キーでも、最後に触ったジッパーを開け閉めできる（共有の画面を出している間は止める）
  document.addEventListener('keydown', e => {
    if (shareViewOpen()){
      if (e.key === 'Escape') closeShareView();
      return;
    }
    if (!$('cam-view').classList.contains('hidden')) return;  // カメラの確認画面を出している間も止める
    if (!active) return;
    if (e.key === 'ArrowDown' || e.key === 'ArrowRight'){ setP(active, active.p + KEY_STEP); e.preventDefault(); }
    else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft'){ setP(active, active.p - KEY_STEP); e.preventDefault(); }
  });

  // ---------- 隠しコマンド ----------
  // 成功すると、次に付けるジッパーが黄金になる
  function secretCommand(){ nextGold = true; }

  // PC：数字キーを SECRET_KEYS の順に押す
  let keyLog = '';
  document.addEventListener('keydown', e => {
    keyLog = (keyLog + (e.key.length === 1 ? e.key : ' ')).slice(-SECRET_KEYS.length);
    if (keyLog !== SECRET_KEYS) return;
    keyLog = '';
    secretCommand();
  });

  // スマホ：ゲーム画面の4隅を同時に CORNER_HOLD 秒押さえ続ける
  const cornerTouches = new Map();   // 隅を押さえている指（pointerId → 隅の番号）
  let cornerTimer = 0;
  let cornerGesture = false;         // 2つ以上の隅を同時に押さえた（指を離したときのボタンの反応を止める）
  function cornerOf(x, y){
    const g = $('stage').getBoundingClientRect();
    const l = x < g.left + CORNER_SIZE, r = x > g.right - CORNER_SIZE, t = y < g.top + CORNER_SIZE, b = y > g.bottom - CORNER_SIZE;
    return t && l ? 0 : t && r ? 1 : b && l ? 2 : b && r ? 3 : -1;
  }
  const heldCorners = () => new Set(cornerTouches.values()).size;
  document.addEventListener('pointerdown', e => {
    if (e.pointerType !== 'touch') return;
    const c = cornerOf(e.clientX, e.clientY);
    if (c < 0) return;
    cornerTouches.set(e.pointerId, c);
    if (heldCorners() >= 2) cornerGesture = true;
    if (heldCorners() === 4 && !cornerTimer){
      cornerTimer = setTimeout(() => { cornerTimer = 0; secretCommand(); }, CORNER_HOLD * 1000);
    }
  }, true);
  const cornerRelease = e => {
    if (!cornerTouches.delete(e.pointerId)) return;
    if (cornerTimer && heldCorners() < 4){ clearTimeout(cornerTimer); cornerTimer = 0; }   // 1本でも離したらやり直し
    if (cornerTouches.size === 0) setTimeout(() => { cornerGesture = false; }, 400);
  };
  document.addEventListener('pointerup', cornerRelease, true);
  document.addEventListener('pointercancel', cornerRelease, true);
  // 隅にボタンがあっても、隅を押さえたあと指を離したときにボタンが反応しないようにする
  document.addEventListener('click', e => {
    if (cornerGesture){ e.preventDefault(); e.stopPropagation(); }
  }, true);

  // iPhone(Safari)で長押しや指の移動により文字選択・拡大鏡が出てドラッグが奪われるのを防ぐ
  document.addEventListener('touchstart', e => { if (e.target === cv) e.preventDefault(); }, { passive:false });
  document.addEventListener('touchmove', e => { if (drag || drawing) e.preventDefault(); }, { passive:false });
  // 共有の文面だけは選んでコピーできるようにする
  document.addEventListener('selectstart', e => {
    const t = e.target.nodeType === 1 ? e.target : e.target.parentElement;
    if (t && t.closest('#share-text')) return;
    e.preventDefault();
  });
  document.addEventListener('contextmenu', e => { if (e.target === cv) e.preventDefault(); });

  // スマホでのダブルタップ拡大を防ぐ（拡大すると元に戻せなくなるため）
  // 写真選択ボタンは除外する（止めるとファイル選択が開かないことがある）
  let lastTouchEnd = 0;
  document.addEventListener('touchend', e => {
    if (e.target instanceof Element && e.target.closest('.pick')) return;
    const now = Date.now();
    if (now - lastTouchEnd < 350) e.preventDefault();
    lastTouchEnd = now;
  }, { passive:false });

  // ---------- 写真の読み込み ----------
  // blob: のURLを<img>に渡す方式は、表示する環境によっては読み込みが禁止されていて全部失敗するので使わない。
  // まず createImageBitmap でファイルから直接作り、使えなければ data: URL で読む
  function loadImage(file){
    const viaDataUrl = () => new Promise((resolve, reject) => {
      const fr = new FileReader();
      fr.onload = () => {
        const im = new Image();
        im.onload = () => resolve(im);
        im.onerror = reject;
        im.src = fr.result;
      };
      fr.onerror = reject;
      fr.readAsDataURL(file);
    });
    if (window.createImageBitmap) return createImageBitmap(file).catch(viaDataUrl);
    return viaDataUrl();
  }

  [0, 1].forEach(i => {
    const input = $('file' + i), text = $('pickText' + i), label = text.textContent;
    input.addEventListener('change', () => {
      const f = input.files && input.files[0];
      if (!f) return;
      loadImage(f).then(im => {
        if (imgs[i] && imgs[i].close) imgs[i].close();  // 前のImageBitmapのメモリを解放
        imgs[i] = im;
        renderLayer(i);
        requestDraw();
      }).catch(() => {
        text.textContent = 'この画像は読み込めません';
        setTimeout(() => { text.textContent = label; }, 1500);
      }).finally(() => { input.value = ''; });  // 空にするのは読み込みが終わってから
    });
  });

  // ---------- 最初から入れておく写真 ----------
  // 外：レンガの壁、中：人の写真。写真を選ぶと置き換わる
  const DEFAULT_IMAGES = [
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
  ];
  DEFAULT_IMAGES.forEach((src, i) => {
    const im = new Image();
    im.onload = () => {
      if (imgs[i]) return;  // 読み込み中に写真が選ばれていたら、そちらを優先する
      imgs[i] = im;
      renderLayer(i);
      requestDraw();
    };
    im.src = src;
  });

  // ---------- カメラ ----------
  // ボタンを押すたびに「オフ → 外の写真をカメラに → 中の写真をカメラに → オフ」と切り替える。
  // 外は背面カメラ（目の前の景色）、中はインカメラ（自分）を使う。インカメラは鏡のように左右反転して映す
  const CAM_STATES = [
    { layer: -1, label: '',   name: 'オフ' },
    { layer: 0,  label: '外', name: '外の写真', facing: 'environment' },
    { layer: 1,  label: '中', name: '中の写真', facing: 'user' },
  ];
  const cam = { state: 0, layer: -1, stream: null, mirror: false, token: 0, loop: 0 };
  const camBtn = $('cam'), camLabel = $('cam-label'), video = $('cam-video');

  // 映像を、写真と同じく画面いっぱいに収まるよう拡大し、はみ出た分は切って描く
  function drawVideo(c, g){
    const vw = video.videoWidth, vh = video.videoHeight;
    if (!cam.stream || video.readyState < 2 || !vw || !vh) return false;
    const s = Math.max(c.width / vw, c.height / vh), w = vw * s, h = vh * s;
    g.save();
    if (cam.mirror){ g.translate(c.width, 0); g.scale(-1, 1); }
    g.drawImage(video, (c.width - w) / 2, (c.height - h) / 2, w, h);
    g.restore();
    return true;
  }

  // 映像が動いている間は毎フレーム、カメラの層だけ描き直して表示する
  // （ジッパーの描き直しが待っているときは、そちらがまとめて表示する）
  function camFrame(){
    cam.loop = requestAnimationFrame(camFrame);
    if (cam.layer < 0 || !W || !H) return;
    const c = layers[cam.layer];
    if (!drawVideo(c, c.getContext('2d'))) return;
    texs[cam.layer].needsUpdate = true;
    if (!drawQueued) renderer.render(scene, camera);
  }

  function stopStream(){
    if (cam.stream) cam.stream.getTracks().forEach(t => t.stop());
    cam.stream = null;
    video.srcObject = null;
  }

  function showCamState(){
    const st = CAM_STATES[cam.state];
    camBtn.setAttribute('aria-pressed', String(cam.state !== 0));
    camBtn.setAttribute('aria-label', 'カメラ：' + st.name);
    camLabel.textContent = st.label;
  }

  // カメラを使えなかったとき：オフに戻し、対象の写真のボタンに一時的に知らせる
  function camFailed(layer){
    const old = cam.layer;
    cam.state = 0; cam.layer = -1;
    stopStream();
    showCamState();
    if (old >= 0) renderLayer(old);
    requestDraw();
    const text = $('pickText' + layer), label = layer === 0 ? '外の写真' : '中の写真';
    text.textContent = 'カメラを使えません';
    setTimeout(() => { text.textContent = label; }, 1500);
  }

  async function setCamState(n){
    const token = ++cam.token;  // 連打したときは最後の操作だけを生かす
    const prev = cam.layer, st = CAM_STATES[n];
    // カメラを切り替えたら、それまでカメラを映していた写真に、その時の映像を止めて残す
    if (prev >= 0 && prev !== st.layer) keepFrame(prev);
    cam.state = n; cam.layer = st.layer;
    stopStream();
    showCamState();
    if (st.layer < 0){ requestDraw(); return; }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){ camFailed(st.layer); return; }  // https でないページなど
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: st.facing, width: { ideal: 1280 }, height: { ideal: 1280 } }, audio: false,
      });
      if (token !== cam.token){ stream.getTracks().forEach(t => t.stop()); return; }
      cam.stream = stream;
      // 実際に使えたカメラの向きで反転を決める（向きが分からない機器では、インカメラを頼んだときだけ反転）
      const facing = stream.getVideoTracks()[0]?.getSettings?.().facingMode;
      cam.mirror = facing ? facing === 'user' : st.facing === 'user';
      video.srcObject = stream;
      await video.play().catch(() => {});
      if (!cam.loop) camFrame();
    } catch (e){
      if (token === cam.token) camFailed(st.layer);
    }
  }

  // 今映っている映像を、その写真として残す（カメラの層の下描きには、もう最新の映像が描いてある）
  function keepFrame(layer){
    if (!cam.stream || video.readyState < 2) return;
    const src = layers[layer], c = document.createElement('canvas');
    c.width = src.width; c.height = src.height;
    c.getContext('2d').drawImage(src, 0, 0);
    if (imgs[layer] && imgs[layer].close) imgs[layer].close();
    imgs[layer] = c;
  }

  // 初めてカメラボタンを押したときは、カメラを使うことを知らせる画面を出し、許可を押したらカメラを起動する
  // （このページを開いている間は、2回目からは出さない）
  let camAllowed = false;
  const camView = $('cam-view');
  const camViewOpen = () => !camView.classList.contains('hidden');
  function openCamView(){
    camView.classList.remove('hidden');
    $('cam-allow').focus({ preventScroll:true });
  }
  function closeCamView(){
    camView.classList.add('hidden');
    camBtn.focus({ preventScroll:true });
  }
  $('cam-close').addEventListener('click', closeCamView);
  $('cam-allow').addEventListener('click', () => {
    camAllowed = true;
    closeCamView();
    setCamState(1);
  });
  camView.addEventListener('pointerdown', e => e.stopPropagation());
  document.addEventListener('keydown', e => {
    if (camViewOpen() && e.key === 'Escape') closeCamView();
  });

  // 切り替え方は削除トグルと同じ（タッチは pointerdown、キーボード操作は click）
  const toggleCam = () => {
    if (!camAllowed){ openCamView(); return; }
    setCamState((cam.state + 1) % CAM_STATES.length);
  };
  camBtn.addEventListener('pointerdown', e => { e.preventDefault(); toggleCam(); });
  camBtn.addEventListener('click', e => { if (e.detail === 0) toggleCam(); });

  // 写真を選んだら、その写真のカメラはやめて選んだ写真を使う
  [0, 1].forEach(i => $('file' + i).addEventListener('change', () => {
    if (cam.layer === i) setCamState(0);
  }));

  // 別のアプリから戻ったとき、止まった映像を再開する
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden && cam.stream) video.play().catch(() => {});
  });

  // ---------- 開始 ----------
  resize();
  addEventListener('resize', resize);
})();
